{"output": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # Between any two marks on a common row or column, color the intervening
    # background cells with the fixed bridge color 2.
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            if b - a <= 4:
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(ys, ys[1:]):
            if b - a <= 4:
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

if __name__ == '__main__':
